
public class PatternTwo {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		for(int i = 0; i < 3; i++){	
			for(int j = 0; j <= i; j++){
				System.out.print('*'); // dont write ln it will print it on new line
		}
		
			System.out.println();
}
		}


}
